const {defaults:DEFAULTS,specs,groups,blankGames,fresh,scores,derive,champion,placements,gameSkipped,record,sourceLabel,valid,migrate}=Bracket;
const KEY='ncf-legends-2026-placement-v3';
let data=fresh(),active='MLBB',selected=null,storageOK=true,migrated=false;
try {const stored=JSON.parse(localStorage.getItem(KEY));if(valid(stored,specs.map(s=>s.bestOf)))data=stored;else {const old=JSON.parse(localStorage.getItem('ncf-legends-2026-double-v2'))||JSON.parse(localStorage.getItem('ncf-legends-2026-v1'));if(valid(old,Array(15).fill(3))||valid(old,Array(7).fill(3))){data=migrate(old);migrated=true;localStorage.setItem(KEY,JSON.stringify(data));}}}catch{storageOK=false;}
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true}catch{storageOK=false}render()}
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function resultText(i,ms,t){const place=placements(ms).indexOf(ms[i].winner);return ms[i].winner===null?'':`${t.names[ms[i].winner]} ${place>=0?`finish in place ${place+1}`:'advance'}.`;}
function chooseGame(i,g,side){const t=data[active];if(!record(t,i,g,side))return;save();showMatch(i);const ms=derive(t);if(ms[i].winner!==null)notify(resultText(i,ms,t));}
function matchHTML(i,m,t){const complete=m.winner!==null;return `<button class="match" data-match="${i}" aria-label="Open match ${i+1}: ${m.seeds.map(s=>s===null?'To be decided':esc(t.names[s])).join(' versus ')}"><div class="match-title">${specs[i].title}</div><div class="match-label"><span>M${String(i+1).padStart(2,'0')} · BO${specs[i].bestOf}</span><span class="${m.ready?'ready':''}">${complete?'COMPLETE':m.ready?'VIEW SERIES ↗':'UPCOMING'}</span></div>${m.seeds.map((seed,k)=>`<div class="team-row ${seed===null?'pending':''} ${complete&&seed===m.winner?'winner':''}"><span class="seed">${seed===null?'—':String(seed+1).padStart(2,'0')}</span><span>${seed===null?sourceLabel(specs[i].sources[k]):esc(t.names[seed])}</span><span class="score">${complete&&seed===m.winner?'✓ &nbsp; ':''}${m.ready?m.score[k]:'—'}</span></div>`).join('')}</button>`}
function render(){const t=data[active],ms=derive(t),champ=champion(ms),complete=ms.filter(m=>m.winner!==null).length,total=12;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===active));$('#saved').textContent=storageOK?'Saved on this browser':'Storage unavailable · keep this tab open';$('#progress').innerHTML=`<div style="width:${complete/total*100}%"></div>`;$('#progress').setAttribute('aria-label',`${complete} of ${total} matches completed`);
$('#board').innerHTML=groups.map(group=>`<section class="bracket-group"><div class="group-title">${group.title}<span>${group.note}</span></div><div class="bracket-grid">${group.columns.map(([name,ids])=>`<div class="column"><div class="column-heading">${name}</div><div class="matches">${ids.map(i=>matchHTML(i,ms[i],t)).join('')}</div></div>`).join('')}</div></section>`).join('')+`<section class="standings"><h2>Final placements</h2><ol>${placements(ms).map((seed,i)=>`<li><span>${i+1}</span><strong>${seed===null?'To be decided':esc(t.names[seed])}</strong></li>`).join('')}</ol></section>`;document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>showMatch(Number(b.dataset.match)));drawBracketConnectors();}
function showMatch(i){selected=i;const t=data[active],m=derive(t)[i],games=t.games[i];const name=k=>m.seeds[k]===null?'TBD':esc(t.names[m.seeds[k]]);$('#match-content').innerHTML=`<div class="dialog-top"><p class="eyebrow">${active} / M${String(i+1).padStart(2,'0')} · BO${specs[i].bestOf}</p><button data-close aria-label="Close match">✕</button></div><h2>${specs[i].title}</h2><p>${m.ready?`Tap the winner next to each team. First to ${specs[i].winTarget} ${active==='CODM'?'map':'game'} wins takes the series.`:'Complete the preceding matches to unlock this series.'}</p><div class="series-score"><span>${name(0)}</span><span>${m.score[0]} : ${m.score[1]}</span><span>${name(1)}</span></div><div class="rounds" style="--game-count:${games.length}">${games.map((v,g)=>{const skip=gameSkipped(games,g,specs[i].winTarget);const locked=!m.ready||(g>0&&games[g-1]===null)||skip;return `<div class="round"><h3>${active==='CODM'?'MAP':'GAME'} 0${g+1}</h3>${[0,1].map(k=>`<button data-game="${g}" data-side="${k}" ${locked?'disabled':''} class="${v===k?'chosen':''}" aria-pressed="${v===k}">${name(k)} &nbsp; ${v===k?'✓':'+'}</button>`).join('')}<p>${skip?'Not needed':v!==null?'Winner recorded':locked?'Awaiting prior game':'Select winner'}</p></div>`}).join('')}</div><div class="dialog-bottom"><span>${m.winner===null?`Best of ${specs[i].bestOf} · ${specs[i].winTarget} wins to take the series`:esc(resultText(i,derive(t),t))}</span><button data-close>Done</button></div><p>To correct a result, tap the selected winner again or choose the other team. Later games and affected matchups will clear.</p>`;$('#match-content').querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>chooseGame(i,Number(b.dataset.game),Number(b.dataset.side)));bindClose();if(!$('#match-dialog').open)$('#match-dialog').showModal();}
function bindClose(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close())}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{active=b.dataset.tab;render()});
$('#edit').onclick=()=>{$('#team-fields').innerHTML=data[active].names.map((n,i)=>`<label>SEED ${String(i+1).padStart(2,'0')}<input name="team${i}" value="${esc(n)}" required maxlength="32" aria-label="Team ${i+1}"></label>`).join('');$('#team-dialog').showModal()};
$('#team-form').onsubmit=e=>{e.preventDefault();const names=Array.from($('#team-fields').querySelectorAll('input')).map(x=>x.value.trim());if(names.some(n=>!n))return notify('Every team needs a name.');if(new Set(names.map(n=>n.toLowerCase())).size<8)return notify('Please give each team a unique name.');data[active].names=names;save();$('#team-dialog').close();notify('Team names updated.')};
$('#reset').onclick=()=>{if(confirm(`Reset all ${active} results? Team names will stay. This cannot be undone.`)){data[active].games=blankGames();save();notify(`${active} bracket reset.`)}};
function exportPDF(){const t=data[active],ms=derive(t);const header=`<h1>NCF INTRAMURALS 2026 · ${active}</h1><p>SINGLE ELIMINATION WITH FULL PLACEMENTS | 8 TEAMS | 12 SERIES | 11 BO3 + BO5 CHAMPIONSHIP</p>`;$('#print-view').innerHTML=groups.map(group=>`<section>${header}<h2>${group.title}</h2><p>${group.note}</p><div class="print-bracket">${group.columns.map(([title,ids])=>`<div><h3>${title}</h3><div class="print-column">${ids.map(i=>`<div class="print-match" data-match="${i}"><small>M${i+1} · ${specs[i].title} · BO${specs[i].bestOf}</small>${ms[i].seeds.map((seed,k)=>`<div>${seed===null?sourceLabel(specs[i].sources[k]):esc(t.names[seed])} — ${ms[i].score[k]}${seed!==null&&seed===ms[i].winner?' ✓':''}</div>`).join('')}</div>`).join('')}</div></div>`).join('')}</div><footer>Exported ${new Date().toLocaleString('en-PH',{timeZone:'Asia/Manila'})} (Philippine time) · Current bracket state</footer></section>`).join('')+`<section>${header}<h2>FINAL PLACEMENTS</h2><table><thead><tr><th>Place</th><th>Team</th></tr></thead><tbody>${placements(ms).map((seed,i)=>`<tr><td>${i+1}</td><td>${seed===null?'To be decided':esc(t.names[seed])}</td></tr>`).join('')}</tbody></table></section><section>${header}<h2>${active==='CODM'?'MAP':'GAME'} RESULTS</h2><table><thead><tr><th>Match</th><th>Teams</th>${[1,2,3,4,5].map(n=>`<th>${active==='CODM'?'Map':'Game'} ${n}</th>`).join('')}<th>Winner</th></tr></thead><tbody>${ms.map((m,i)=>`<tr><td>M${i+1} · BO${specs[i].bestOf}</td><td>${m.seeds.map(seed=>seed===null?'TBD':esc(t.names[seed])).join(' vs ')}</td>${[0,1,2,3,4].map(g=>`<td>${g>=specs[i].bestOf?'—':gameSkipped(t.games[i],g,specs[i].winTarget)?'Not needed':t.games[i][g]===null?'Pending':esc(t.names[m.seeds[t.games[i][g]]]??'TBD')}</td>`).join('')}<td>${m.winner===null?'Pending':esc(t.names[m.winner])}</td></tr>`).join('')}</tbody></table></section>`;document.title=`NCF-2026-${active}-12-Series`;drawBracketConnectors();window.print();document.title='Call of Legends · NCF Intramurals 2026';}
$('#export').onclick=exportPDF;bindClose();render();
if(migrated)notify('New format: team names, quarterfinals and championship semifinals retained. Other series start fresh.');
